package com.tanerinal.education.service;import com.tanerinal.education.domain.*;import com.tanerinal.education.mapper.*;import com.tanerinal.education.web.dto.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class ReceiptReviewService{private final ShopOrderMapper orders;private final ReviewMapper reviews;private final ProductCatalogService catalog;public ReceiptReviewService(ShopOrderMapper orders,ReviewMapper reviews,ProductCatalogService catalog){this.orders=orders;this.reviews=reviews;this.catalog=catalog;}@Transactional public ShopOrderResponse receive(AppUser user,Long orderId){orders.lock(user.getId(),orderId).orElseThrow(()->new ResourceNotFoundException("Order not found"));if(orders.updateStatus(orderId,"SHIPPED","RECEIVED")!=1)throw new BusinessRuleException("Only shipped orders can be received");orders.insertEvent(orderId,user.getId(),"ORDER_RECEIVED","SHIPPED","RECEIVED","Customer confirmed receipt");return response(orders.find(user.getId(),orderId).orElseThrow());}@Transactional public ProductReviewResponse review(AppUser user,Long itemId,ReviewRequest request){ReviewableItem item=reviews.reviewable(user.getId(),itemId).orElseThrow(()->new BusinessRuleException("Only received order items can be reviewed"));try{reviews.insert(itemId,item.getProductId(),user.getId(),request.rating(),request.comment());}catch(DuplicateKeyException e){throw new BusinessRuleException("This order item was already reviewed");}catalog.invalidate();return ProductReviewResponse.from(reviews.byItem(itemId));}private ShopOrderResponse response(ShopOrderView o){return new ShopOrderResponse(o.getId(),o.getOrderNumber(),o.getStatus(),o.getTotalAmount(),o.getCurrency(),o.getCreatedAt(),orders.items(o.getId()).stream().map(ShopOrderResponse.Item::from).toList(),ShopOrderResponse.Address.from(orders.address(o.getId())),ShopOrderResponse.Payment.from(orders.latestPayment(o.getId()).orElse(null)));}}
